import kotlin.math.min

fun solver(n: Int, m: Int): Int {
    var first = 0
    var second = 0
    var copyN = n
    val point = if (m % 2 == 0) m else m + 1

    while (copyN != point / 2) {
        if (copyN > point / 2) {
            first += copyN - (point / 2)
            copyN = point / 2
        }
        if (copyN < point / 2) {
            copyN *= 2
            first += 1
        }
    }
    first += if (m % 2 == 0) 1 else 2

    copyN = n
    while (copyN != m) {
        if (copyN < m) {
            copyN *= 2
        } else {
            second += copyN - m
            break
        }
        second += 1
    }

    return min(first, second)
}

fun main() {
    val line = readLine() ?: return
    val parts = line.trim().split(" ").map { it.toInt() }
    val n = parts[0]
    val m = parts[1]

    if (n > m) {
        println(n - m)
        return
    }

    var data = mutableMapOf<Int, Int>()
    data[n] = n

    var find = 0
    while (true) {
        val map = mutableMapOf<Int, Int>()
        for (key in data.keys) {
            val x = key
            if (x - 1 >= 1) {
                map[x - 1] = x - 1
                if (x - 1 == m) {
                    println(find + 1)
                    return
                }
            }
            if ((x * 2).toDouble() <= m * 1.5) {
                map[x * 2] = x * 2
                if (x * 2 == m) {
                    println(find + 1)
                    return
                }
            }
        }
        data = map
        find += 1
    }
}
